enum Priority { HIGH(3), MEDIUM(2), LOW(1); final int weight; Priority(int w) { this.weight = w; } }
enum TaskStatus { PENDING, RUNNING, DONE, FAILED, CANCELLED }

class ScheduledTask implements Delayed {
    private final String taskId;
    private final Runnable runnable;
    private volatile long executionTime; // epoch ms (volatile — re-scheduled on retry/recurring)
    private final Priority priority;
    private volatile TaskStatus status = TaskStatus.PENDING;
    private final RetryPolicy retryPolicy;
    private int attempt = 0;
    private final long intervalMs; // 0 = one-time

    public ScheduledTask(Runnable r, long time, Priority p,
                         RetryPolicy policy, long intervalMs) {
        this.taskId = UUID.randomUUID().toString();
        this.runnable = r;
        this.executionTime = time;
        this.priority = p;
        this.retryPolicy = policy;
        this.intervalMs = intervalMs;
    }

    @Override
    public long getDelay(TimeUnit unit) {
        long diffMs = executionTime - System.currentTimeMillis();
        return unit.convert(diffMs, TimeUnit.MILLISECONDS);
    }

    @Override
    public int compareTo(Delayed other) {
        ScheduledTask o = (ScheduledTask) other;
        // Primary: execution time
        int timeCompare = Long.compare(this.executionTime, o.executionTime);
        if (timeCompare != 0) return timeCompare;
        // Tie-break: priority (higher weight = earlier)
        int priCompare = Integer.compare(o.priority.weight, this.priority.weight);
        if (priCompare != 0) return priCompare;
        // Final: taskId for deterministic ordering
        return this.taskId.compareTo(o.taskId);
    }

    public boolean isRecurring() { return intervalMs > 0; }
    public String getTaskId() { return taskId; }
    public Runnable getRunnable() { return runnable; }
    public TaskStatus getStatus() { return status; }
    public void setStatus(TaskStatus s) { this.status = s; }
    public int getAttempt() { return attempt; }
    public void incrementAttempt() { this.attempt++; }
    public RetryPolicy getRetryPolicy() { return retryPolicy; }
    public void setExecutionTime(long t) { this.executionTime = t; }
    public long getIntervalMs() { return intervalMs; }
}

interface RetryPolicy {
    boolean shouldRetry(int attempt);
    long nextDelayMs(int attempt);

    RetryPolicy NO_RETRY = new RetryPolicy() {
        public boolean shouldRetry(int a) { return false; }
        public long nextDelayMs(int a) { return 0; }
    };
}

class ExponentialBackoff implements RetryPolicy {
    private final long baseDelayMs;
    private final int maxRetries;
    private final double multiplier;

    public ExponentialBackoff(long baseDelayMs, int maxRetries, double multiplier) {
        this.baseDelayMs = baseDelayMs;
        this.maxRetries = maxRetries;
        this.multiplier = multiplier;
    }

    @Override
    public boolean shouldRetry(int attempt) {
        return attempt < maxRetries;
    }

    @Override
    public long nextDelayMs(int attempt) {
        // Delay = base * multiplier^attempt
        // With jitter to prevent thundering herd
        double delay = baseDelayMs * Math.pow(multiplier, attempt);
        double jitter = ThreadLocalRandom.current().nextDouble(0.8, 1.2);
        return (long) (delay * jitter);
    }
}

class TaskScheduler {
    private final DelayQueue<ScheduledTask> queue = new DelayQueue<>();
    private final ExecutorService workerPool;
    private final Thread dispatcher;
    private final ConcurrentHashMap<String, ScheduledTask> allTasks = new ConcurrentHashMap<>();
    private volatile boolean running = true;

    public TaskScheduler(int numWorkers) {
        this.workerPool = Executors.newFixedThreadPool(numWorkers);
        this.dispatcher = new Thread(this::dispatchLoop, "task-dispatcher");
        this.dispatcher.setDaemon(true);
        this.dispatcher.start();
    }

    // ── Public API ──────────────────────────
    public String scheduleAt(Runnable task, long epochMs,
                             Priority priority, RetryPolicy policy) {
        if (!running)
            throw new SchedulerStoppedException("Scheduler stopped");
        ScheduledTask st = new ScheduledTask(task, epochMs, priority, policy, 0);
        allTasks.put(st.getTaskId(), st);
        queue.put(st);
        return st.getTaskId();
    }

    public String scheduleEvery(Runnable task, long intervalMs,
                                Priority priority) {
        if (!running)
            throw new SchedulerStoppedException("Scheduler stopped");
        long firstRun = System.currentTimeMillis() + intervalMs;
        ScheduledTask st = new ScheduledTask(
            task, firstRun, priority, RetryPolicy.NO_RETRY, intervalMs);
        allTasks.put(st.getTaskId(), st);
        queue.put(st);
        return st.getTaskId();
    }

    public boolean cancel(String taskId) {
        ScheduledTask st = allTasks.get(taskId);
        if (st == null) return false;
        if (st.getStatus() == TaskStatus.PENDING) {
            st.setStatus(TaskStatus.CANCELLED);
            return true;
        }
        return false; // already running or done
    }

    public void shutdown() {
        running = false;
        dispatcher.interrupt();
        workerPool.shutdown();
        try {
            workerPool.awaitTermination(30, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    // ── Dispatcher loop ─────────────────────
    private void dispatchLoop() {
        while (running) {
            try {
                ScheduledTask task = queue.take(); // blocks until due
                if (task.getStatus() == TaskStatus.CANCELLED) {
                    allTasks.remove(task.getTaskId());
                    continue;
                }
                task.setStatus(TaskStatus.RUNNING);
                workerPool.submit(() -> executeTask(task));
            } catch (InterruptedException e) {
                if (!running) break; // shutdown signal
                Thread.currentThread().interrupt();
            }
        }
    }

    // ── Worker execution logic ──────────────
    private void executeTask(ScheduledTask task) {
        // Double-check cancellation just before execution
        if (task.getStatus() == TaskStatus.CANCELLED) {
            allTasks.remove(task.getTaskId());
            return;
        }

        try {
            task.getRunnable().run();

            // Success path
            if (task.isRecurring()) {
                // Reschedule for next interval
                task.setExecutionTime(
                    System.currentTimeMillis() + task.getIntervalMs());
                task.setStatus(TaskStatus.PENDING);
                queue.put(task);
            } else {
                task.setStatus(TaskStatus.DONE);
                allTasks.remove(task.getTaskId());
            }
        } catch (Exception e) {
            // Failure path — retry with backoff?
            task.incrementAttempt();
            if (task.getRetryPolicy().shouldRetry(task.getAttempt())) {
                long delay = task.getRetryPolicy().nextDelayMs(task.getAttempt());
                task.setExecutionTime(System.currentTimeMillis() + delay);
                task.setStatus(TaskStatus.PENDING);
                queue.put(task);
            } else {
                task.setStatus(TaskStatus.FAILED);
                // Optional: send to dead-letter queue / callback
                allTasks.remove(task.getTaskId());
            }
        }
    }
}
